alter table public.areas add column if not exists activo boolean not null default true;
alter table public.ramos add column if not exists activo boolean not null default true;
create unique index if not exists areas_nome_u on public.areas(nome); create unique index if not exists ramos_nome_u on public.ramos(nome); create unique index if not exists cargos_slug_u on public.cargos(slug);
insert into public.areas (nome, slug) select v.nome, v.slug from (values ('Agricultura, pescas e veterinária','agricultura-pescas-e-veterinaria'),('Petróleo, gás e minas','petroleo-gas-e-minas'),('Construção e obras','construcao-e-obras'),('Logística e transportes','logistica-e-transportes'),('Hotelaria, turismo e restauração','hotelaria-turismo-e-restauracao'),('Comunicação, marketing e design','comunicacao-marketing-e-design'),('Recursos humanos','recursos-humanos'),('Banca e seguros','banca-e-seguros'),('Indústria e produção','industria-e-producao'),('Ambiente e energia','ambiente-e-energia'),('Artes, cultura e desporto','artes-cultura-e-desporto'),('Serviços gerais e manutenção','servicos-gerais-e-manutencao'),('Diplomacia e relações internacionais','diplomacia-e-relacoes-internacionais'),('Imobiliário','imobiliario')) v(nome, slug) where not exists (select 1 from public.areas a where a.nome=v.nome);
insert into public.ramos (nome) select v.nome from (values ('Energia e águas'),('Imobiliário'),('Media e publicidade'),('Consultoria e auditoria'),('Segurança privada'),('Farmacêutico'),('Bebidas e alimentar'),('Têxtil e confecções'),('Automóvel'),('Aviação'),('Marítimo e portuário'),('Limpeza e facility'),('Distribuição e grosso'),('Retalho e supermercados'),('Turismo'),('Advocacia'),('Ensino superior privado'),('Investigação'),('Organizações internacionais'),('Igrejas e associações'),('Empresa familiar / pequeno negócio'),('Trabalho doméstico')) v(nome) where not exists (select 1 from public.ramos r where r.nome=v.nome);
update public.ramos set activo=false where nome='Outro';
