create table if not exists public.niveis (id smallint generated by default as identity primary key, nome text not null unique, descricao text, ordem smallint not null default 0, activo boolean not null default true);
alter table public.niveis enable row level security;
create policy "leitura publica" on public.niveis for select to anon, authenticated using (true);
create policy "admin gere niveis" on public.niveis for all to authenticated using ((select privado.is_admin())) with check ((select privado.is_admin()));
insert into public.niveis (nome, descricao, ordem) values ('Estagiário','Estagiário ou trainee',1),('Profissional, sem chefia','Ex.: professor, enfermeiro, contabilista, vendedor',2),('Sénior / especialista, sem chefia','Muita experiência ou especialização, sem equipa a seu cargo',3),('Chefia','Coordenador, supervisor, chefe de secção ou de turno',4),('Direcção','Chefe de departamento, director, gerente geral',5) on conflict (nome) do nothing;
create table if not exists public.sugestoes (
  id bigint generated by default as identity primary key,
  tipo text not null check (tipo in ('cargo','area','ramo','nivel')),
  texto text not null check (char_length(texto) between 2 and 120),
  autor_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  partilha_id uuid references public.partilhas(id) on delete set null,
  estado text not null default 'pendente' check (estado in ('pendente','aprovada','rejeitada')),
  resultado_id integer,
  criado_em timestamptz not null default now(),
  resolvido_em timestamptz,
  resolvido_por uuid references auth.users(id)
);
create index if not exists sugestoes_estado on public.sugestoes(estado, tipo);
create index if not exists sugestoes_autor on public.sugestoes(autor_id);
create index if not exists sugestoes_partilha on public.sugestoes(partilha_id);
alter table public.sugestoes enable row level security;
create policy "sugerir" on public.sugestoes for insert to authenticated with check (autor_id = (select auth.uid()) and estado = 'pendente' and resolvido_por is null);
create policy "ver as minhas ou admin" on public.sugestoes for select to authenticated using (autor_id = (select auth.uid()) or (select privado.is_admin()));
create policy "admin resolve" on public.sugestoes for update to authenticated using ((select privado.is_admin())) with check ((select privado.is_admin()));
create policy "admin apaga" on public.sugestoes for delete to authenticated using ((select privado.is_admin()));
alter table public.partilhas add column if not exists area_texto text, add column if not exists ramo_texto text;
